<?php
ini_set('display_errors','0');header('Content-Type: application/json; charset=utf-8');require_once __DIR__ . '/_vault_helpers.php';
try{if($_SERVER['REQUEST_METHOD']!=='GET'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;}$db=vault_db();$actor=vault_require_auth();vault_require_verified();$id=(int)($_GET['document_id']??0);$grant=$_SESSION['vault_download_grant']??null;$token=(string)($_GET['download_token']??'');if(!$grant||$grant['actor']!==$actor||$grant['document_id']!==$id||$grant['expires']<time()||!hash_equals((string)$grant['token'],$token)){ApiResponse::forbidden('Email verification required before download.');exit;}unset($_SESSION['vault_download_grant']);$doc=vault_require_document_access($db,$id,$actor);$cipher=!empty($doc['encrypted_blob'])?$doc['encrypted_blob']:@file_get_contents(vault_storage_dir().DIRECTORY_SEPARATOR.$doc['encrypted_filename']);if($cipher===false||$cipher===null||hash('sha256',$cipher)!==$doc['ciphertext_sha256']){vault_log($db,(int)$doc['owner_id'],$actor,$id,'tamper_detected');ApiResponse::serverError('Vault file integrity check failed.');exit;}$key=($doc['encryption_version']==='aes-256-gcm-db-v1')?vault_derived_key((int)$doc['owner_id']):vault_master_key();$plain=openssl_decrypt($cipher,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$doc['iv'],$doc['auth_tag']);if($plain===false||hash('sha256',$plain)!==$doc['plaintext_sha256']){vault_log($db,(int)$doc['owner_id'],$actor,$id,'tamper_detected');ApiResponse::serverError('Vault file integrity check failed.');exit;}vault_log($db,(int)$doc['owner_id'],$actor,$id,'download');if(!headers_sent()){header('Content-Type: '.$doc['mime_type']);header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($doc['original_filename'])).'"');header('Content-Length: '.strlen($plain));}echo $plain;}catch(Throwable $e){Logger::error('Vault download failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to download vault document.');}
?>